import type { MedicalTerm } from "./types";

const termsExtra500_4: MedicalTerm[] = [
  { id: "akalaziya", term: "Akalaziya", category: "Gastroenterologiya", shortDesc: "Qizilo'ngach mushaklarining buzilishi", fullDesc: "Akalaziya — qizilo'ngachning pastki sfinkteri to'g'ri bo'shamay, ovqat oshqozonga o'tishini qiyinlashtiradigan holat. Yutish qiyinligi, ko'krak og'rig'i va ovqatning qaytishi asosiy belgilar.", origin: "Yunoncha 'a' (yo'q) va 'khalasis' (bo'shashish) so'zlaridan.", treatment: "Pnevmatik dilatatsiya, botulinum toksin in'ektsiyasi, Geller miotomiyasi jarrohlik.", prevention: "Maxsus oldini olish yo'q, erta tashxis muhim.", recommendations: "Ovqatni maydalab yeng, vertikal holatda yeb bo'lgach 30 daqiqa o'tiring.", source: "AGA gastroenterologiya qo'llanmasi" },
  { id: "akondroplaziya", term: "Akondroplaziya", category: "Genetika", shortDesc: "Suyak o'sishining genetik buzilishi", fullDesc: "Akondroplaziya — eng ko'p uchraydigan dvarfizm (pakanalik) turi. FGFR3 genidagi mutatsiya sababli tog'ay suyakka aylanishi buziladi. Qisqa oyoq-qo'llar va nisbatan katta bosh xos.", origin: "Yunoncha 'a' (yo'q), 'khondros' (tog'ay) va 'plasis' (rivojlanish) so'zlaridan.", treatment: "Vosoretid (vosoritide) — yangi dori; ortopedik jarrohlik.", prevention: "Genetik maslahat, prenatal diagnostika.", recommendations: "Bolalar ortopedida muntazam kuzatilishi kerak.", source: "OMIM genetik ma'lumotlar bazasi" },
  { id: "akromegaliya", term: "Akromegaliya", category: "Endokrinologiya", shortDesc: "O'sish gormonining ortiqcha ishlab chiqarilishi", fullDesc: "Akromegaliya — kattalarda gipofiz bezining adenomasi sababli o'sish gormoni ortiqcha ishlab chiqariladigan holat. Qo'l, oyoq va yuz suyaklari kattalashadi.", origin: "Yunoncha 'akron' (chekka) va 'megas' (katta) so'zlaridan.", treatment: "Jarrohlik (transsfenoidal), oktreotid, pegvisomant.", prevention: "Erta tashxis va davolash asoratlarni kamaytiradi.", recommendations: "Endokrinolog va neyrojarroh kuzatuvida bo'ling.", source: "Endocrine Society qo'llanmasi" },
  { id: "aldosteronizm", term: "Aldosteronizm", category: "Endokrinologiya", shortDesc: "Aldosteron gormonining ortiqchaligi", fullDesc: "Aldosteronizm — buyrak usti bezlarining aldosteron gormonini ortiqcha ishlab chiqarishi. Natijada gipertoniya, gipokalemiya va mushak zaiflanishi kuzatiladi.", origin: "Aldosteron gormoni nomidan. 1955-yilda Conn sindromi sifatida tasvirlangan.", treatment: "Spironolakton, eplerenon; adenomada jarrohlik.", prevention: "Rezistent gipertoniyada tekshirish tavsiya etiladi.", recommendations: "Tuz iste'molini kamaytiring, kaliy darajasini nazorat qiling.", source: "J Clinical Endocrinology & Metabolism" },
  { id: "amiloidoz", term: "Amiloidoz", category: "Kasallik", shortDesc: "Organlarda amiloid oqsil to'planishi", fullDesc: "Amiloidoz — noto'g'ri bukilgan amiloid oqsillarning turli organlarda (yurak, buyrak, jigar) to'planib, ularning funksiyasini buzadigan kasallik guruhi.", origin: "Lotincha 'amylum' (kraxmal) va yunoncha 'eidos' (ko'rinish) so'zlaridan.", treatment: "Ximioterapiya, organ transplantatsiyasi, tafamidis (yurak amiloidozida).", prevention: "Surunkali yallig'lanish kasalliklarini davolash.", recommendations: "Nefrolog, kardiolog va gematolog bilan birgalikda kuzatish.", source: "ASH amiloidoz qo'llanmasi" },
  { id: "anizometropia", term: "Anizometropia", category: "Oftalmologiya", shortDesc: "Ko'zlar refraksiyasining farqlanishi", fullDesc: "Anizometropia — ikki ko'zdagi sinish kuchining sezilarli farqlanishi. Amblyopiya (dangasa ko'z) rivojlanishiga olib kelishi mumkin, ayniqsa bolalarda.", origin: "Yunoncha 'anisos' (teng emas), 'metron' (o'lchov) va 'ops' (ko'z) so'zlaridan.", treatment: "Ko'zoynak, kontakt linza, refraktiv jarrohlik.", prevention: "Bolalarda erta ko'z tekshiruvi.", recommendations: "3 yoshgacha birinchi ko'z tekshiruvidan o'tish.", source: "AAO oftalmologiya qo'llanmasi" },
  { id: "antifosfolipid_sindromi", term: "Antifosfolipid sindromi", category: "Immunologiya", shortDesc: "Qon ivish buzilishi autoimmun kasallik", fullDesc: "Antifosfolipid sindromi — antifosfolipid antijemlari sababli qon tomirlarda tromboz hosil bo'lishi va homiladorlikda asoratlar (tushish) kuzatiladigan autoimmun holat.", origin: "Fosfolipidlarga qarshi antijemlarga bog'liq.", treatment: "Antikoagulyantlar (varfarin, geparin), aspirinning kichik dozalari.", prevention: "Tashxis qo'yilganda profilaktik antikoagulyant terapiya.", recommendations: "Homiladorlik rejalashtirayotgan ayollar albatta tekshirilishi kerak.", source: "ACR revmatologiya qo'llanmasi" },
  { id: "aortit", term: "Aortit", category: "Kardiologiya", shortDesc: "Aorta devorining yallig'lanishi", fullDesc: "Aortit — aortaning yallig'lanishi. Takayasu arteriti, gigant hujayra arteriti va sifilis sababli bo'lishi mumkin. Aorta anevrizmasi va stenoriga olib keladi.", origin: "Lotincha 'aorta' va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Kortikosteroidlar, immunosuppressorlar, jarrohlik.", prevention: "Asosiy kasalliklarni o'z vaqtida davolash.", recommendations: "MR-angiografiya bilan muntazam kuzatish.", source: "European Heart Journal" },
  { id: "aplastik_anemiya", term: "Aplastik anemiya", category: "Kasallik", shortDesc: "Suyak iligi funksiyasining pasayishi", fullDesc: "Aplastik anemiya — suyak iligining yetarli miqdorda qon hujayralari ishlab chiqara olmasligi. Pansitopeniya (barcha qon hujayralari kamayishi) kuzatiladi. Jiddiy, hayotga xavfli holat.", origin: "Yunoncha 'a' (yo'q) va 'plasis' (shakllanish) so'zlaridan.", treatment: "Suyak iligi transplantatsiyasi, immunosuppressiv terapiya, qon quyish.", prevention: "Toksik kimyoviy moddalarga aloqani kamaytirish.", recommendations: "Gematolog nazoratida bo'lish, infeksiyadan himoyalanish.", source: "ASH gematologiya qo'llanmasi" },
  { id: "artroskopiya", term: "Artroskopiya", category: "Jarrohlik", shortDesc: "Bo'g'imni kamera bilan tekshirish", fullDesc: "Artroskopiya — bo'g'im ichiga kichik kamera (artroskop) kiritib, diagnostika va jarrohlik amallarini bajarish. Tizza, yelka va boshqa bo'g'imlarda qo'llaniladi.", origin: "Yunoncha 'arthron' (bo'g'im) va 'skopein' (ko'rish) so'zlaridan.", treatment: "Menisk yirtilishi, xovuz tanali operatsiyalar, sinovektomiya.", prevention: "Sport travmalaridan ehtiyot bo'lish.", recommendations: "Jarrohlikdan keyin fizioterapiya muhim.", source: "AAOS ortopediya qo'llanmasi" },
  { id: "astsit", term: "Astsit", category: "Gastroenterologiya", shortDesc: "Qorin bo'shlig'ida suyuqlik to'planishi", fullDesc: "Astsit — qorin bo'shlig'ida ortiqcha suyuqlik to'planishi. Eng ko'p jigar tsirrozi sababli, lekin yurak yetishmovchiligi, saraton va infeksiya ham sabab bo'lishi mumkin.", origin: "Yunoncha 'askites' (meshga o'xshash) so'zidan.", treatment: "Diuretiklar, natriy cheklash, paratsentez, TIPS protsedurasi.", prevention: "Jigar kasalliklarini o'z vaqtida davolash, spirtli ichimliklardan voz kechish.", recommendations: "Kunlik tana vaznini o'lchash, tuz iste'molini cheklash.", source: "AASLD jigar kasalliklari qo'llanmasi" },
  { id: "ateroskleroz_obliterans", term: "Ateroskleroz obliterans", category: "Kardiologiya", shortDesc: "Oyoq arteriyalarining torayishi", fullDesc: "Ateroskleroz obliterans — oyoq arteriyalarida aterosklerotik plakalar to'planib, qon oqimini cheklovchi kasallik. Intermittent claudication (yurish paytida og'riq) asosiy belgi.", origin: "Yunoncha 'athero' (bo'tqa) va lotincha 'obliterans' (yo'q qiluvchi) so'zlaridan.", treatment: "Stentlash, bypass jarrohlik, angioplastika, dorilar (silostazol).", prevention: "Chekishni tashllash, qandli diabet va xolesterinni nazorat qilish.", recommendations: "Kundalik yurish mashqlari muhim.", source: "ACC/AHA periferik arteriya kasalliklari qo'llanmasi" },
  { id: "atopik_dermatit", term: "Atopik dermatit", category: "Dermatologiya", shortDesc: "Surunkali qichishuvchi teri yallig'lanishi", fullDesc: "Atopik dermatit (ekzema) — terining surunkali yallig'lanishi, qichish, quruqlik va toshmalar bilan namoyon bo'ladi. Ko'pincha bolalikda boshlanadi va allergik rinit, astma bilan birga kuzatiladi.", origin: "Yunoncha 'atopos' (g'ayrioddiy) va 'derma' (teri) so'zlaridan.", treatment: "Emolentlar, topikal kortikosteroidlar, kalsineyrin ingibitorlari, dupilumab.", prevention: "Teri namligini saqlash, allergenlardan qochish.", recommendations: "Kundalik namlantiruvchi krem qo'llash, issiq suv bilan cho'milmaslik.", source: "AAD atopik dermatit qo'llanmasi" },
  { id: "atrioventrikulyar_blokada", term: "Atrioventrikulyar blokada", category: "Kardiologiya", shortDesc: "Yurak o'tkazuvchanligining buzilishi", fullDesc: "AV blokada — elektr signallarning bo'lmachalardan qorinchalarga o'tishining buzilishi. I, II va III darajalar mavjud. III daraja to'liq blokada — kardiostimulyator kerak.", origin: "Lotincha 'atrium' (bo'lmacha) va 'ventriculus' (qorincha) so'zlaridan.", treatment: "I daraja — kuzatish, III daraja — kardiostimulyator o'rnatish.", prevention: "Yurak kasalliklarini o'z vaqtida davolash.", recommendations: "Muntazam EKG monitoring.", source: "ESC kardiologiya qo'llanmasi" },
  { id: "bakteriemiya", term: "Bakteriemiya", category: "Mikrobiologiya", shortDesc: "Qonda bakteriyalar mavjudligi", fullDesc: "Bakteriemiya — qon oqimida bakteriyalar bo'lishi. O'tkinchi (tish cho'tkalash), birlamchi yoki ikkilamchi bo'lishi mumkin. Sepsisga olib kelishi mumkin.", origin: "Yunoncha 'bakterion' (tayoqcha) va 'haima' (qon) so'zlaridan.", treatment: "Empirik antibiotik terapiya, qon kulturasi natijalariga qarab maqsadli davolash.", prevention: "Infeksiya o'choqlarini o'z vaqtida sanatsiya qilish.", recommendations: "Tez shifokorga murojaat qilish, qon kulturasi topshirish.", source: "IDSA infeksion kasalliklar qo'llanmasi" },
  { id: "balanit", term: "Balanit", category: "Urologiya", shortDesc: "Jinsiy a'zo boshchasining yallig'lanishi", fullDesc: "Balanit — erkaklar jinsiy a'zosi boshchasining yallig'lanishi. Qizarish, shish, og'riq va ajralma asosiy belgilar. Gigiena buzilishi, infeksiya va qandli diabet sabab bo'lishi mumkin.", origin: "Yunoncha 'balanos' (boshcha) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Antifungal, antibakterial kremlar, gigiena ta'minlash.", prevention: "Shaxsiy gigiena saqlash, qandli diabetni nazorat qilish.", recommendations: "Surunkali holatda urolog konsultatsiyasi.", source: "EAU urologiya qo'llanmasi" },
  { id: "bartolinit", term: "Bartolinit", category: "Ginekologiya", shortDesc: "Bartolin bezi yallig'lanishi", fullDesc: "Bartolinit — vulvadagi Bartolin bezlarining yallig'lanishi va absess hosil bo'lishi. Og'riq, shish va yurish qiyinlashishi xos belgilar.", origin: "Daniyalik anatom Caspar Bartholin nomi bilan.", treatment: "Antibiotiklar, marsupializatsiya, drenaj.", prevention: "Shaxsiy gigiena, JYIK dan himoyalanish.", recommendations: "Takroriy holatlarda marsupializatsiya jarrohlik tavsiya etiladi.", source: "ACOG ginekologiya qo'llanmasi" },
  { id: "bazedov_kasalligi", term: "Bazedov kasalligi (Greyvs)", category: "Endokrinologiya", shortDesc: "Qalqonsimon bez gipertiroidizmi", fullDesc: "Bazedov kasalligi — autoimmun gipertiroidizm. Qalqonsimon bez kengayadi, yurak urishi tezlashadi, tana vazni tushadi, ko'zlar bo'rtadi (ekzoftalm). TSH retseptori antijemlari sabab.", origin: "Nemis shifokor Karl von Basedow va irlandiyalik Robert Graves nomlari bilan.", treatment: "Tionamidlar (tiamazol), radioaktiv yod, tiroidektomiya.", prevention: "Genetik moyillik mavjud, oldini olish qiyin.", recommendations: "Endokrinolog nazoratida gormon darajalarini muntazam tekshirish.", source: "ATA qalqonsimon bez qo'llanmasi" },
  { id: "bilirubinoemiya", term: "Bilirubinoemiya", category: "Bioximiya", shortDesc: "Qonda bilirubin darajasining oshishi", fullDesc: "Bilirubinoemiya — qonda bilirubin konsentratsiyasining oshishi. Jigar kasalliklari, gemoliz yoki o't yo'llari tiqilishi sababli bo'ladi. Sariqlik (jigar sariqlig'i) bilan namoyon bo'ladi.", origin: "Lotincha 'bilis' (o't) va 'ruber' (qizil) so'zlaridan.", treatment: "Asosiy sababga qarab: gepatit davolash, o't toshi olib tashlash, fototerapiya (yangi tug'ilganlarda).", prevention: "Jigar salomatligini saqlash, gepatit emlashi.", recommendations: "Sariqlik belgilari paydo bo'lganda zudlik bilan shifokorga murojaat.", source: "AASLD jigar kasalliklari qo'llanmasi" },
  { id: "biopsiya", term: "Biopsiya", category: "Diagnostika", shortDesc: "To'qima namunasini olish tekshiruvi", fullDesc: "Biopsiya — tashxis qo'yish uchun organizmdan to'qima namunasi olish va mikroskop ostida tekshirish. Saraton, yallig'lanish va boshqa kasalliklarni aniqlashda muhim.", origin: "Yunoncha 'bios' (hayot) va 'opsis' (ko'rish) so'zlaridan.", treatment: "Igna biopsiyasi, intsizion, ektsizion, endoskopik biopsiya turlari.", prevention: "Erta tashxis uchun profilaktik skrining.", recommendations: "Gistopatologik xulosani mutaxassis bilan muhokama qiling.", source: "CAP patologiya qo'llanmasi" },
  { id: "bradiaritmiya", term: "Bradiaritmiya", category: "Kardiologiya", shortDesc: "Yurak ritmining sekinlashishi", fullDesc: "Bradiaritmiya — yurak urishi daqiqada 60 dan kam bo'lgan holat. Sinusli bradikardiya, AV blokada va boshqa turlar mavjud. Bosh aylanish va hushdan ketish sabab bo'lishi mumkin.", origin: "Yunoncha 'bradys' (sekin) va 'arrhythmia' (ritm buzilishi) so'zlaridan.", treatment: "Kardiostimulyator, atropin (shoshilinch holatlarda).", prevention: "Yurak kasalliklarini o'z vaqtida davolash.", recommendations: "Bosh aylanish, hushdan ketish bo'lsa darhol shifokorga murojaat.", source: "ACC/AHA aritmiya qo'llanmasi" },
  { id: "bronxoektaziya", term: "Bronxoektaziya", category: "Kasallik", shortDesc: "Bronxlarning qaytmas kengayishi", fullDesc: "Bronxoektaziya — bronxlar devorining surunkali yallig'lanish va infeksiya sababli qaytmas kengayishi. Surunkali yo'tal, yiringli balg'am va qon tupurish xos.", origin: "Yunoncha 'bronkhos' (bronx) va 'ektasis' (kengayish) so'zlaridan.", treatment: "Antibiotiklar, bronxodilatatorlar, fizikal terapiya (posturalniy drenaj), og'ir hollarda jarrohlik.", prevention: "O'pka infeksiyalarini o'z vaqtida davolash, emlash.", recommendations: "Kundalik nafas mashqlari va posturalniy drenaj.", source: "BTS bronxoektaziya qo'llanmasi" },
  { id: "bursit", term: "Bursit", category: "Travmatologiya", shortDesc: "Bo'g'im sumkasining yallig'lanishi", fullDesc: "Bursit — bo'g'imlar atrofidagi bursa (suyuqlik bilan to'lgan qopchalar) yallig'lanishi. Yelka, tirsak, tizza va son bo'g'imlarida ko'p uchraydi.", origin: "Lotincha 'bursa' (qopcha) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Dam olish, muz qo'yish, NSAIDlar, kortikosteroid in'ektsiyasi.", prevention: "Ortiqcha zo'riqishdan qochish, himoya moslamalaridan foydalanish.", recommendations: "Sport mashqlaridan oldin isitish va cho'zish mashqlari.", source: "AAOS ortopediya qo'llanmasi" },
  { id: "vagotomiya", term: "Vagotomiya", category: "Jarrohlik", shortDesc: "Vagus nervini kesish operatsiyasi", fullDesc: "Vagotomiya — oshqozon kislotasi ishlab chiqarishini kamaytirish uchun vagus nervining shoxlarini kesish jarrohlik amali. Zamonaviy davolashda kamroq qo'llaniladi.", origin: "Lotincha 'vagus' (sarson) va yunoncha 'tome' (kesish) so'zlaridan.", treatment: "Trunkulyar, selektiv va supraselektiv vagotomiya turlari.", prevention: "PPI (proton pompa ingibitorlari) vagotomiya o'rniga ko'proq qo'llanilmoqda.", recommendations: "Dori bilan davolanmaydigan yara kasalligida ko'rib chiqiladi.", source: "Sabiston jarrohlik darsligi" },
  { id: "vaskulit", term: "Vaskulit", category: "Immunologiya", shortDesc: "Qon tomirlar devorining yallig'lanishi", fullDesc: "Vaskulit — qon tomirlar devorining autoimmun yallig'lanishi. Kichik, o'rta va katta tomirlar zararlanishi mumkin. Teri, buyrak, o'pka va boshqa organlar zararlanadi.", origin: "Lotincha 'vasculum' (tomir) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Kortikosteroidlar, siklofosfamid, rituksimab.", prevention: "Autoimmun jarayon — oldini olish qiyin.", recommendations: "Revmatolog nazoratida muntazam tekshiruvlar.", source: "ACR vaskulit qo'llanmasi" },
  { id: "ventrikulomegaliya", term: "Ventrikulomegaliya", category: "Nevrologiya", shortDesc: "Miya qorinchalari kengayishi", fullDesc: "Ventrikulomegaliya — miyaning lateral qorinchalari 10 mm dan katta bo'lishi. Gidrotsefaliya bilan bog'liq, lekin mustaqil holat ham bo'lishi mumkin. Homiladorlik UZIda aniqlanishi mumkin.", origin: "Lotincha 'ventriculus' (qorincha) va yunoncha 'megale' (katta) so'zlaridan.", treatment: "Shuntirovanie, endoskopik ventrikulostomiya.", prevention: "Homiladorlikda folat kislota qabul qilish.", recommendations: "Neyrolog va neyrojarroh konsultatsiyasi.", source: "AIUM prenatal UZI qo'llanmasi" },
  { id: "vitiligo", term: "Vitiligo", category: "Dermatologiya", shortDesc: "Teri pigmentatsiyasining yo'qolishi", fullDesc: "Vitiligo — melanositlar yo'q bo'lib, teridagi pigmentatsiya kamayadigan surunkali kasallik. Oq dog'lar paydo bo'ladi. Autoimmun mexanizm asosiy sabab deb hisoblanadi.", origin: "Lotincha 'vitium' (nuqson) so'zidan.", treatment: "Topikal kortikosteroidlar, kalsineyrin ingibitorlari, UVB fototerapiya, jarrohlik (teri transplantatsiya).", prevention: "Autoimmun kasallik — oldini olish qiyin.", recommendations: "Quyoshdan himoyalanish (SPF 50+), psixologik qo'llab-quvvatlash.", source: "AAD vitiligo qo'llanmasi" },
  { id: "ganglion_kista", term: "Ganglion kista", category: "Travmatologiya", shortDesc: "Bo'g'im atrofidagi suyuqlik to'plangan shish", fullDesc: "Ganglion kista — bo'g'im yoki pay qinidan o'sib chiqadigan suyuqlik to'plangan yumaloq shish. Eng ko'p bilakning orqa tomonida uchraydi. Og'riqsiz yoki engil og'riqli.", origin: "Yunoncha 'ganglion' (tugun) so'zidan.", treatment: "Kuzatish, aspiratsiya, jarrohlik olib tashlash.", prevention: "Maxsus oldini olish yo'q.", recommendations: "O'z-o'zidan so'rilishi mumkin. Shishib og'riyotgan bo'lsa shifokorga murojaat.", source: "AAOS ortopediya qo'llanmasi" },
  { id: "gastrit_eroziv", term: "Eroziv gastrit", category: "Gastroenterologiya", shortDesc: "Oshqozon shilliq qavatining eroziyasi", fullDesc: "Eroziv gastrit — oshqozon shilliq qavatida yuzaki yaralar (eroziyalar) paydo bo'lishi. NSAID dorilar, spirtli ichimliklar va stress asosiy sabablari. Qon ketishi mumkin.", origin: "Yunoncha 'gaster' (oshqozon) va lotincha 'erosio' (yemirish) so'zlaridan.", treatment: "PPI (omeprazol), antatsidlar, sababni bartaraf etish.", prevention: "NSAID dorilarni ehtiyotkorlik bilan qo'llash, spirt va chekishni tashllash.", recommendations: "Ovqatlanish rejimini tartibga solish, stress boshqarish.", source: "AGA gastroenterologiya qo'llanmasi" },
  { id: "gastroparez", term: "Gastroparez", category: "Gastroenterologiya", shortDesc: "Oshqozon bo'shashishi sekinlashishi", fullDesc: "Gastroparez — oshqozon mushaklarining normaldagidan sekin ishlashi, ovqat hazm bo'lishining kechikishi. Qandli diabet, jarrohlikdan keyingi holat va idiopatik sabablari bor.", origin: "Yunoncha 'gaster' (oshqozon) va 'paresis' (zaiflik) so'zlaridan.", treatment: "Metoklopramid, eritromisin, gastrik elektrostimulyator.", prevention: "Qandli diabetni yaxshi nazorat qilish.", recommendations: "Kam miqdorda, tez-tez ovqatlanish, kam tolali ovqat.", source: "AGA gastroparez qo'llanmasi" },
  { id: "gemangioma", term: "Gemangioma", category: "Onkologiya", shortDesc: "Qon tomir o'smasi (xavfsiz)", fullDesc: "Gemangioma — qon tomirlarning xavfsiz (benign) o'smasi. Eng ko'p jigar va teridagi turlari uchraydi. Yangi tug'ilgan chaqaloqlarda teri gemangiomalari tez-tez kuzatiladi.", origin: "Yunoncha 'haima' (qon), 'angeion' (tomir) va '-oma' (o'sma) so'zlaridan.", treatment: "Kuzatish, propranolol (bolalar gemangiomasida), lazer, jarrohlik.", prevention: "Kongenital — oldini olish mumkin emas.", recommendations: "Aksariyat bolalar gemangiomalari o'z-o'zidan so'riladi.", source: "AAP pediatriya qo'llanmasi" },
  { id: "gemofiliya_b", term: "Gemofiliya B", category: "Kasallik", shortDesc: "IX faktor yetishmovchiligi", fullDesc: "Gemofiliya B (Kristmas kasalligi) — qon ivish IX faktorining yetishmovchiligi bilan kechadigan irsiy kasallik. Gemofiliya A ga qaraganda kamroq uchraydi (15-20%).", origin: "Birinchi bemor Stephen Christmas nomi bilan atalgan.", treatment: "IX faktor konsentratlarini in'ektsiya qilish, emicizumab.", prevention: "Genetik maslahat, prenatal diagnostika.", recommendations: "Gematolog nazoratida bo'lish, jarohatlardan ehtiyot bo'lish.", source: "WFH gemofiliya qo'llanmasi" },
  { id: "gerpes_zoster", term: "Gerpes zoster (bel temir)", category: "Kasallik", shortDesc: "Suvchechak virusining qayta faollashishi", fullDesc: "Gerpes zoster — varicella-zoster virusining nerv tugunlarida yashirinib, immunitet pasayganda qayta faollashishi. Bir tomonlama og'riqli toshmalar xos.", origin: "Yunoncha 'herpes' (surish) va 'zoster' (kamar) so'zlaridan.", treatment: "Asiklovir, valasiklovir (72 soat ichida boshlash kerak), og'riqsizlantirgichlar.", prevention: "Shingrix emlashi (50 yosh ustidagilar uchun).", recommendations: "O'z vaqtida antiviral davoni boshlash postgerpertik nevralgiya xavfini kamaytiradi.", source: "CDC immunizatsiya qo'llanmasi" },
  { id: "gidronefroz", term: "Gidronefroz", category: "Urologiya", shortDesc: "Buyrakning kengayishi", fullDesc: "Gidronefroz — siydik oqimining to'silishi sababli buyrak jomchasi va kosachalarining kengayishi. Buyrak toshlari, o'sma va tug'ma anomaliyalar sababli bo'ladi.", origin: "Yunoncha 'hydor' (suv), 'nephros' (buyrak) va '-osis' (holat) so'zlaridan.", treatment: "Sababga qarab: stent, nefrostomiya, jarrohlik.", prevention: "Buyrak toshlarini oldini olish, siydik yo'li infeksiyalarini davolash.", recommendations: "Belda og'riq, qonli siydik chiqsa zudlik bilan shifokorga murojaat.", source: "EAU urologiya qo'llanmasi" },
  { id: "giperbilirubinemiya", term: "Giperbilirubinemiya", category: "Bioximiya", shortDesc: "Qonda bilirubin darajasi oshishi", fullDesc: "Giperbilirubinemiya — qonda bilirubin konsentratsiyasining me'yordan oshishi. To'g'ridan-to'g'ri (konjugirlangan) va bilvosita (nokonjugirlangan) turlari mavjud.", origin: "Yunoncha 'hyper' (ortiqcha), lotincha 'bilis' (o't) va 'ruber' (qizil) so'zlaridan.", treatment: "Sababga qarab: fototerapiya, almashinish transfuziya, jarrohlik.", prevention: "Jigar salomatligini saqlash, yangi tug'ilgan chaqaloqlarni kuzatish.", recommendations: "Yangi tug'ilganlarda sariqlik darajasini muntazam tekshirish.", source: "AAP neonatal sariqlik qo'llanmasi" },
  { id: "giperkalsiemiya", term: "Giperkalsiemiya", category: "Endokrinologiya", shortDesc: "Qonda kalsiy darajasining oshishi", fullDesc: "Giperkalsiemiya — qondagi kalsiy darajasining me'yordan oshishi. Giperparatireoidizm va saraton eng ko'p sabablar. Buyrak toshlari, qorin og'rig'i, mushak zaiflanishi xos.", origin: "Yunoncha 'hyper' (ortiqcha) va lotincha 'calcium' (kalsiy) so'zlaridan.", treatment: "Izotonik NaCl infuziyasi, furosemid, bisfosfonatlar, kalsitonin.", prevention: "Asosiy sababni erta aniqlash va davolash.", recommendations: "Yetarli suyuqlik iste'mol qilish, qo'shimcha kalsiy va D vitamini qabul qilishni shifokor bilan kelishuv.", source: "AACE endokrinologiya qo'llanmasi" },
  { id: "giperkoagulyatsiya", term: "Giperkoagulyatsiya", category: "Kasallik", shortDesc: "Qonning ortiqcha ivishi holati", fullDesc: "Giperkoagulyatsiya (trombofiliya) — qonning ortiqcha ivishga moyilligi. Chuqur venoz tromboz va o'pka arteriyasi tromboemboliyasi xavfini oshiradi.", origin: "Yunoncha 'hyper' (ortiqcha) va lotincha 'coagulatio' (ivish) so'zlaridan.", treatment: "Antikoagulyantlar (geparin, varfarin, rivaroksaban).", prevention: "Uzoq harakatsizlikda profilaktik antikoagulyant, harakat.", recommendations: "Oilaviy trombofiliya mavjud bo'lsa genetik test topshirish.", source: "ASH trombofiliya qo'llanmasi" },
  { id: "giperparatireoidizm", term: "Giperparatireoidizm", category: "Endokrinologiya", shortDesc: "Paratgormonning ortiqcha ishlab chiqarilishi", fullDesc: "Giperparatireoidizm — parashildsimon bezlarning paratgormonni ortiqcha ishlab chiqarishi. Qonda kalsiy oshadi, suyaklar yupqalashadi, buyrak toshlari hosil bo'ladi.", origin: "Yunoncha 'hyper' (ortiqcha), 'para' (yonida) va 'thyreos' (qalqon) so'zlaridan.", treatment: "Jarrohlik (paratireoidektomiya), sinakalsit.", prevention: "Vitamin D yetishmovchiligini bartaraf etish.", recommendations: "Suyak zichligi va buyrak tekshiruvlari muntazam ravishda.", source: "AACE endokrinologiya qo'llanmasi" },
  { id: "gipersplenizm", term: "Gipersplenizm", category: "Kasallik", shortDesc: "Taloqning ortiqcha faoliyati", fullDesc: "Gipersplenizm — taloqning qon hujayralarini haddan tashqari ko'p yo'q qilishi. Anemiya, leykopeniya va trombositopeniya kuzatiladi. Jigar tsirrozi, infeksiyalar va autoimmun kasalliklar sabab.", origin: "Yunoncha 'hyper' (ortiqcha), lotincha 'splen' (taloq) va '-ism' (holat) so'zlaridan.", treatment: "Asosiy sababni davolash, og'ir hollarda splenektomiya.", prevention: "Jigar kasalliklarini o'z vaqtida davolash.", recommendations: "Splenektomiyadan oldin pnevmokokk, meningokokk va Hib emlashlarini olish.", source: "ASH gematologiya qo'llanmasi" },
  { id: "gipotalamik_sindrom", term: "Gipotalamik sindrom", category: "Endokrinologiya", shortDesc: "Gipotalamus funksiyasining buzilishi", fullDesc: "Gipotalamik sindrom — miyaning gipotalamus qismidagi buzilish sababli ishtaha, harorat, uyqu va gormon ishlab chiqarish tartibining o'zgarishi.", origin: "Yunoncha 'hypo' (pastda) va 'thalamus' (xona) so'zlaridan.", treatment: "Gormon almashtirish terapiyasi, sababga qarab jarrohlik.", prevention: "Miya shikastlanishini oldini olish.", recommendations: "Endokrinolog va neyrolog birgalikda kuzatishi kerak.", source: "J Clinical Endocrinology & Metabolism" },
  { id: "gipotireoidizm_subklinik", term: "Subklinik gipotireoidizm", category: "Endokrinologiya", shortDesc: "Engil qalqonsimon bez yetishmovchiligi", fullDesc: "Subklinik gipotireoidizm — TSH biroz oshgan, lekin T4 normal darajada. Belgilar sezilmasligi mumkin, lekin charchoq va vazn oshishi kuzatilishi mumkin.", origin: "Lotincha 'sub' (ostida) va 'clinicus' (klinik) so'zlaridan.", treatment: "TSH 10 dan yuqori bo'lganda levotiroksin boshlash ko'rib chiqiladi.", prevention: "Yod yetarli iste'mol qilish.", recommendations: "6-12 oyda bir TSH darajasini tekshirish.", source: "ATA qalqonsimon bez qo'llanmasi" },
  { id: "gistiostioz", term: "Gistiositoz", category: "Onkologiya", shortDesc: "Gistiositlarning g'ayritabiiy ko'payishi", fullDesc: "Gistiositoz — gistiositlar (makrofaglar) ning g'ayritabiiy ko'payishi. Langerhans hujayra gistiositozi eng ko'p uchraydigan turi. Suyak, teri va o'pkani zararlaydi.", origin: "Yunoncha 'histion' (to'qima) va 'kytos' (hujayra) so'zlaridan.", treatment: "Ximioterapiya, steroidlar, jarrohlik, nurli davolash.", prevention: "Sabablar noma'lum — oldini olish qiyin.", recommendations: "Pediatrik onkolog nazoratida bo'lish.", source: "Histiocyte Society qo'llanmasi" },
  { id: "xolangit", term: "Xolangit", category: "Gastroenterologiya", shortDesc: "O't yo'llarining yallig'lanishi", fullDesc: "Xolangit — o't yo'llarining bakterial infeksiya sababli yallig'lanishi. Sharko triadi: isitma, sariqlik va o'ng qovurg'a osti og'rig'i xos belgilar.", origin: "Yunoncha 'khole' (o't) va 'angeion' (tomir) so'zlaridan.", treatment: "Antibiotiklar, ERXPG bilan o't yo'lini ochish, jarrohlik.", prevention: "O't toshi kasalligini o'z vaqtida davolash.", recommendations: "Sharko belgilari paydo bo'lsa tezkor tibbiy yordam.", source: "AASLD jigar kasalliklari qo'llanmasi" },
  { id: "xondromalatsiya", term: "Xondromalatsiya patella", category: "Travmatologiya", shortDesc: "Tizza qopqog'i tog'ayining yumsashi", fullDesc: "Xondromalatsiya patella — tizza qopqog'i (patella) ostidagi tog'ayning yumsashi va yemirilishi. Yoshlarda, ayniqsa sportchilarda ko'p uchraydi. Tizzada og'riq, g'irchilash xos.", origin: "Yunoncha 'khondros' (tog'ay) va 'malakia' (yumshoqliq) so'zlaridan.", treatment: "Fizioterapiya, NSAIDlar, tizza bilan bog'liq mashqlar.", prevention: "To'g'ri sport texnikasi, mushaklar muvozanatini saqlash.", recommendations: "Quadriceps mushagini mustahkamlash mashqlari.", source: "AAOS ortopediya qo'llanmasi" },
  { id: "xorioretinit", term: "Xorioretinit", category: "Oftalmologiya", shortDesc: "Ko'z to'r va qon parda yallig'lanishi", fullDesc: "Xorioretinit — ko'zning xorioid (qon parda) va retina (to'r parda) qismlarining yallig'lanishi. Toksoplazma, sifilis va tuberkulyoz sabab bo'lishi mumkin.", origin: "Yunoncha 'khorion' (parda) va 'retina' (to'r) so'zlaridan.", treatment: "Antibiotiklar/antiparazitar dorilar, kortikosteroidlar.", prevention: "Toksoplazma infeksiyasidan ehtiyot bo'lish (xom go'sht, mushuk).", recommendations: "Ko'rishni saqlash uchun erta davolash muhim.", source: "AAO oftalmologiya qo'llanmasi" },
  { id: "tselluloz", term: "Tsellulit (teri infeksiyasi)", category: "Dermatologiya", shortDesc: "Teri va teri osti to'qimasining infeksiyasi", fullDesc: "Tsellulit — teri va teri osti to'qimasining bakterial infeksiyasi. Qizarish, shish, issiqlik va og'riq xos belgilar. Streptokokk va stafilokokk ko'p sabab.", origin: "Lotincha 'cellula' (hujayra) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Antibiotiklar (amoksitsillin-klavulanat, sefalosporinlar).", prevention: "Teri yaralari va tirnaqlarni tozalab, dezinfeksiya qilish.", recommendations: "Qizarish tarqalayotgan bo'lsa zudlik bilan shifokorga murojaat.", source: "IDSA teri infeksiyalari qo'llanmasi" },
  { id: "shizoaffektiv", term: "Shizoaffektiv buzilish", category: "Psixiatriya", shortDesc: "Shizofreniya va kayfiyat buzilishi birgaligi", fullDesc: "Shizoaffektiv buzilish — shizofreniya simptomlarining (gallyutsinatsiya, delüziya) depressiya yoki maniya simptomlari bilan birgalikda kuzatilishi.", origin: "Yunoncha 'skhizein' (bo'lmoq) va lotincha 'affectus' (kayfiyat) so'zlaridan.", treatment: "Antipsixotiklar, kayfiyatni barqarorlashtiruvchilar, antidepressantlar.", prevention: "Erta tashxis va davolash prognozni yaxshilaydi.", recommendations: "Psixiatr nazoratida uzluksiz dori qabul qilish.", source: "APA psixiatriya qo'llanmasi" },
  { id: "shigelloz", term: "Shigelloz (dizenteriya)", category: "Kasallik", shortDesc: "Ichak infeksiyasi — qonli diareya", fullDesc: "Shigelloz — Shigella bakteriyalari sababli bo'ladigan o'tkir ichak infeksiyasi. Qonli va shilimshiqli diareya, isitma, qorin og'rig'i xos belgilar.", origin: "Yapon mikrobiolgi Kiyoshi Shiga nomi bilan.", treatment: "Antibiotiklar (siprofloksatsin, azitromitsin), suyuqlik almashtirish.", prevention: "Qo'lni yuvish, toza suv iste'mol qilish, gigiena saqlash.", recommendations: "Dehidratatsiya belgilarini kuzatish, bolalarda ayniqsa ehtiyot bo'lish.", source: "CDC infeksion kasalliklar qo'llanmasi" },
  { id: "enurez", term: "Enurez", category: "Pediatriya", shortDesc: "Bolalarda ixtiyorsiz siydik chiqishi", fullDesc: "Enurez — 5 yoshdan katta bolalarda tungi yoki kunduzgi ixtiyorsiz siydik chiqishi. Birlamchi va ikkilamchi turlari mavjud. Genetik moyillik muhim omil.", origin: "Yunoncha 'enourein' (siydik chiqarish) so'zidan.", treatment: "Desmopressin, ogohlantirish qurilmasi, motivatsion terapiya.", prevention: "Yotish oldidan suyuqlik iste'molini cheklash.", recommendations: "Bolani jazolash yoki uyaltirish samarasiz va zararli. Sabar va qo'llab-quvvatlash kerak.", source: "ICCS enurez qo'llanmasi" },
  { id: "epikondilid", term: "Epikondilid (tennis tirsaklari)", category: "Travmatologiya", shortDesc: "Tirsak suyagi o'simtasi yallig'lanishi", fullDesc: "Epikondilid — tirsak suyagining lateral (tashqi) yoki medial (ichki) epikondilida pay yallig'lanishi. 'Tennis tirsagi' va 'golfchi tirsagi' deb ham ataladi.", origin: "Yunoncha 'epi' (ustida) va 'kondylos' (bo'rtiq) so'zlaridan.", treatment: "Dam olish, muz, NSAIDlar, fizioterapiya, kortikosteroid in'ektsiyasi.", prevention: "Sport va mehnatda to'g'ri texnika qo'llash.", recommendations: "Epikondilid bandaji va cho'zish mashqlari.", source: "AAOS ortopediya qo'llanmasi" },
  { id: "eritema_nodosum", term: "Eritema nodosum", category: "Dermatologiya", shortDesc: "Teri osti yog' to'qimasining yallig'lanishi", fullDesc: "Eritema nodosum — boldirning oldingi yuzasida og'riqli qizil tugunlar paydo bo'lishi. Streptokokk infeksiyasi, sarkoidoz, IBD va dorilar sabab bo'lishi mumkin.", origin: "Yunoncha 'erythema' (qizarish) va lotincha 'nodosum' (tugunli) so'zlaridan.", treatment: "NSAIDlar, dam olish, kaliy yodid, kortikosteroidlar.", prevention: "Asosiy sababni aniqlash va davolash.", recommendations: "2-6 hafta ichida o'z-o'zidan tuzaladi, lekin sabab aniqlanishi kerak.", source: "AAD dermatologiya qo'llanmasi" },
  { id: "eritrositoz", term: "Eritrositoz (polisitemiya)", category: "Kasallik", shortDesc: "Qonda qizil qon tanachalarining ko'payishi", fullDesc: "Eritrositoz — qonda eritrotsitlar (qizil qon tanachalari) sonining oshishi. Birlamchi (polisitemiya vera — JAK2 mutatsiyasi) va ikkilamchi (gipoksiya, balandlik) turlari.", origin: "Yunoncha 'erythros' (qizil) va 'kytos' (hujayra) so'zlaridan.", treatment: "Flebotomiya (qon olish), gidroksikarbamid, ruksolitinib.", prevention: "Suyuqlik yetarli iste'mol qilish, chekishni tashllash.", recommendations: "Gematolog nazoratida muntazam qon tekshiruvlari.", source: "ASH polisitemiya qo'llanmasi" },
  { id: "yododefitsit", term: "Yod yetishmovchiligi", category: "Endokrinologiya", shortDesc: "Organizmda yod mineralining kamligi", fullDesc: "Yod yetishmovchiligi — qalqonsimon bez gormonlari ishlab chiqarish uchun zarur yod mineralining yetarli bo'lmasligi. Buqoq, gipotireoidizm va bolalarda aqliy rivojlanish orqada qolishiga sabab.", origin: "Yunoncha 'iodes' (binafsha rangli) so'zidan — yod bug'i rangi.", treatment: "Yodlangan tuz, yod qo'shimchalari, dengiz mahsulotlari.", prevention: "Yodlangan tuz iste'mol qilish, dengiz baliqlarini yeyish.", recommendations: "Homilador va emizikli ayollar uchun yod qo'shimchasi tavsiya etiladi.", source: "JSST yod yetishmovchiligi qo'llanmasi" },
  { id: "ishemik_insult", term: "Ishemik insult", category: "Nevrologiya", shortDesc: "Miya qon aylanishining to'satdan buzilishi", fullDesc: "Ishemik insult — miya arteriyasining tromb yoki embol bilan tiqilib, miya to'qimasiga qon bormay qolishi. Falajlik, nutq buzilishi va hushning o'zgarishi xos belgilar. Tezkor yordam muhim.", origin: "Yunoncha 'iskhein' (ushlab turish) va 'haima' (qon) so'zlaridan.", treatment: "Trombolitik terapiya (4.5 soat ichida), trombektomiya, reabilitatsiya.", prevention: "Gipertoniyani davolash, antikoagulyant terapiya, sog'lom turmush tarzi.", recommendations: "FAST qoidasi: Face, Arms, Speech, Time — belgilarni bilish hayot qutqaradi.", source: "AHA/ASA insult qo'llanmasi" },
  { id: "kardiomiopatiya_gipertrofik", term: "Gipertrofik kardiomiopatiya", category: "Kardiologiya", shortDesc: "Yurak devorining qalinlashishi", fullDesc: "Gipertrofik kardiomiopatiya — yurak mushagi (ayniqsa septum) ning g'ayritabiiy qalinlashishi. Yoshlarda to'satdan o'lim sabablaridan biri. Genetik kasallik.", origin: "Yunoncha 'hyper' (ortiqcha), 'trophe' (oziqlantirish), 'kardia' (yurak) va 'pathos' (kasallik) so'zlaridan.", treatment: "Beta-blokerlar, kalsiy kanal blokerlar, septal mioektomiya, ICD.", prevention: "Oilaviy skrining, sport tibbiyoti tekshiruvi.", recommendations: "Intensiv jismoniy mashqlardan vaqtincha voz kechish kerak bo'lishi mumkin.", source: "ACC/AHA kardiomiopatiya qo'llanmasi" },
  { id: "katarakta_kongenital", term: "Kongenital katarakta", category: "Oftalmologiya", shortDesc: "Tug'ma ko'z gavharining xiralashishi", fullDesc: "Kongenital katarakta — tug'ilishdan mavjud yoki erta bolalikda rivojlanadigan ko'z gavharining xiralashishi. Ambliopiya va ko'rlik sabablaridan biri.", origin: "Yunoncha 'katarrhaktes' (sharshara) so'zidan — ko'rish xiraliksifat.", treatment: "Jarrohlik (gavhrani olib tashlash), kontakt linza yoki IOL.", prevention: "Homiladorlikda krasnuxa infeksiyasidan ehtiyot bo'lish.", recommendations: "Erta tashxis va jarrohlik ko'rish rivojlanishi uchun muhim.", source: "AAO oftalmologiya qo'llanmasi" },
  { id: "keratit", term: "Keratit", category: "Oftalmologiya", shortDesc: "Ko'z shox pardasining yallig'lanishi", fullDesc: "Keratit — ko'zning shox pardasining (kornea) yallig'lanishi. Bakterial, viral (gerpes), fungal va parazitar turlari mavjud. Kontakt linza foydalanuvchilarida ko'p uchraydi.", origin: "Yunoncha 'keras' (shox) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Topikal antibiotik, antiviral yoki antifungal tomchilar, sikloplegiklar.", prevention: "Kontakt linzalarni to'g'ri parvarish qilish, iflos qo'l bilan ko'zni ishqalamaslik.", recommendations: "Ko'z og'rig'i, qizarish va ko'rish pasayishi bo'lsa zudlik bilan oftalmologga murojaat.", source: "AAO kornea kasalliklari qo'llanmasi" },
  { id: "koagulopatiya", term: "Koagulopatiya", category: "Kasallik", shortDesc: "Qon ivish tizimining buzilishi", fullDesc: "Koagulopatiya — qon ivish jarayonining buzilishi. Ortiqcha qon ketishi yoki ortiqcha tromboz hosil bo'lishi mumkin. Irsiy (gemofiliya) yoki orttirilgan (jigar kasalligi, DIC) bo'ladi.", origin: "Lotincha 'coagulatio' (ivish) va yunoncha 'pathos' (kasallik) so'zlaridan.", treatment: "Sababga qarab: ivish faktorlari, K vitamini, plazma transfuziyasi.", prevention: "Jigar salomatligini saqlash, dori ta'sirlarini kuzatish.", recommendations: "Jarrohlikdan oldin ivish testlarini topshirish.", source: "ISTH tromboz va gemostaz qo'llanmasi" },
  { id: "koarktatsiya", term: "Aorta koarktatsiyasi", category: "Kardiologiya", shortDesc: "Aortaning tug'ma torayishi", fullDesc: "Aorta koarktatsiyasi — aortaning tug'ma torayishi, ko'pincha ductus arteriosus yonida. Yuqori qo'llarda gipertoniya, pastki qo'llarda zaiflashgan puls xos.", origin: "Lotincha 'coarctare' (toraytirish) so'zidan.", treatment: "Jarrohlik (toraygan qismni olib tashlash), balloon angioplastika.", prevention: "Tug'ma nuqson — oldini olish qiyin.", recommendations: "Umr bo'yi kardiolog nazoratida bo'lish.", source: "AHA tug'ma yurak nuqsonlari qo'llanmasi" },
  { id: "kollagenoz", term: "Kollagenoz", category: "Immunologiya", shortDesc: "Biriktiruvchi to'qima kasalliklari", fullDesc: "Kollagenoz — biriktiruvchi to'qimaning tizimli autoimmun kasalliklari guruhi. Tizimli qizil bo'richa, skleroderma, dermatomiozit va boshqalar kiradi.", origin: "Yunoncha 'kolla' (yelim) va '-osis' (holat) so'zlaridan.", treatment: "Kortikosteroidlar, immunosuppressorlar, biologik dorilar.", prevention: "Autoimmun kasalliklar — oldini olish qiyin.", recommendations: "Revmatolog nazoratida muntazam tekshiruvlar.", source: "ACR revmatologiya qo'llanmasi" },
  { id: "koprologik_tekshiruv", term: "Koprogramma", category: "Diagnostika", shortDesc: "Najas umumiy tahlili", fullDesc: "Koprogramma — najasning fizikaviy, kimyoviy va mikroskopik tekshiruvi. Hazm qilish buzilishi, ichak infeksiyalari va parazitlarni aniqlashda qo'llaniladi.", origin: "Yunoncha 'kopros' (najas) va 'gramma' (yozuv) so'zlaridan.", treatment: "Diagnostik vosita — kasallikka qarab davolash belgilanadi.", prevention: "Gastroenterologik shikoyatlarda muntazam tekshirish.", recommendations: "Tahlil topshirishdan oldin maxsus dieta saqlash kerak.", source: "ACG gastroenterologiya qo'llanmasi" },
  { id: "kraniostenoz", term: "Kraniostenoz", category: "Pediatriya", shortDesc: "Bola bosh suyagi chokalarining erta qo'shilishi", fullDesc: "Kraniostenoz — chaqaloqda bosh suyagi chokalari (suturalar) ning me'yoridan oldin qo'shilishi. Bosh shakli o'zgaradi, intrakranial bosim oshishi mumkin.", origin: "Yunoncha 'kranion' (bosh suyagi) va 'stenosis' (torayish) so'zlaridan.", treatment: "Jarrohlik (kraniotomiya), endoskopik jarrohlik.", prevention: "Tug'ma holat — oldini olish qiyin.", recommendations: "3 oygacha jarrohlik bajarish eng yaxshi natija beradi.", source: "AANS neyrojarrohlik qo'llanmasi" },
  { id: "kriptorxizm", term: "Kriptorxizm", category: "Pediatriya", shortDesc: "Moyakning yog'imga tushmasligi", fullDesc: "Kriptorxizm — bir yoki ikkala moyakning yog'im (skrotum) ga tushmasligi. Chala tug'ilgan o'g'il bolalarda ko'p uchraydi. Bepushtlik va saraton xavfini oshiradi.", origin: "Yunoncha 'kryptos' (yashirin) va 'orkhis' (moyak) so'zlaridan.", treatment: "Gormon terapiyasi (hCG, GnRH), orxidopeksiya jarrohlik.", prevention: "Homiladorlikda sog'lom turmush tarzi.", recommendations: "6-12 oy orasida jarrohlik tavsiya etiladi.", source: "EAU pediatrik urologiya qo'llanmasi" },
  { id: "ksilometazolin", term: "Ksilometazolin", category: "Farmakologiya", shortDesc: "Burun bitishligi dori vositasi", fullDesc: "Ksilometazolin — burun shilliq qavatining qon tomirlarini toraytirib, burun bitishligini bartaraf etuvchi dori vositasi. Rinit va sinusitda qo'llaniladi.", origin: "Kimyoviy nomi ksilometazolin gidroxloriddan.", treatment: "Burun tomchilari yoki spreylari, 3-5 kundan oshirmay qo'llash.", prevention: "Uzoq muddatli qo'llashdan qochish (burun bog'liqligi rivojlanishi mumkin).", recommendations: "3 kundan ko'p ishlatmang, bolalarda faqat pediatr ruxsati bilan.", source: "BNF dori ma'lumotnomasi" },
  { id: "laktozoz", term: "Laktoza intolerantligi", category: "Gastroenterologiya", shortDesc: "Sut shakarini hazm qila olmaslik", fullDesc: "Laktoza intolerantligi — laktaza fermenti yetishmovchiligi sababli sut shakarini hazm qila olmaslik. Qorin dam bo'lishi, diareya va gaz ko'payishi xos.", origin: "Lotincha 'lac' (sut) va '-osa' (shakar) so'zlaridan.", treatment: "Laktazasiz parhez, laktaza fermenti qo'shimchalari.", prevention: "Laktoza miqdorini asta-sekin oshirish tolerantlikni yaxshilashi mumkin.", recommendations: "Kalsiy manbalarini boshqa ovqatlardan olish (brokoli, badarak).", source: "NIDDK gastroenterologiya qo'llanmasi" },
  { id: "laminektomiya", term: "Laminektomiya", category: "Jarrohlik", shortDesc: "Umurtqa ravoqini olib tashlash jarrohlik", fullDesc: "Laminektomiya — orqa miya kanalini kengaytirish uchun umurtqaning ravoq (lamina) qismini olib tashlash jarrohlik amali. Stenoz va disk grija holatlarida qo'llaniladi.", origin: "Lotincha 'lamina' (plastinka) va yunoncha 'ektome' (kesish) so'zlaridan.", treatment: "Ochiq yoki minimal invaziv texnika bilan bajariladi.", prevention: "Og'ir yuk ko'tarmaslik, to'g'ri gavda holati.", recommendations: "Jarrohlikdan keyin fizioterapiya va reabilitatsiya muhim.", source: "AANS umurtqa jarrohlik qo'llanmasi" },
  { id: "leykoaraioz", term: "Leykoaraioz", category: "Nevrologiya", shortDesc: "Miya oq moddasining o'zgarishi", fullDesc: "Leykoaraioz — miyaning oq moddasida MRT yoki KTda ko'rinadigan o'zgarishlar. Gipertoniya va kichik tomir kasalligi bilan bog'liq. Kognitiv pasayish va insult xavfini oshiradi.", origin: "Yunoncha 'leukos' (oq) va 'araiosis' (siyraklashish) so'zlaridan.", treatment: "Asosiy vaskulyar xavf omillarini nazorat qilish (gipertoniya, diabet).", prevention: "Qon bosimini me'yorda saqlash, sog'lom turmush tarzi.", recommendations: "Neyrolog nazoratida kognitiv funksiyalarni kuzatish.", source: "Lancet Neurology" },
  { id: "limfadenektomiya", term: "Limfadenektomiya", category: "Jarrohlik", shortDesc: "Limfa tugunlarini jarrohlik yo'li bilan olib tashlash", fullDesc: "Limfadenektomiya — saraton davolanishida limfa tugunlarini jarrohlik bilan olib tashlash. O'smaning tarqalish darajasini aniqlash va mintaqaviy nazorat uchun bajariladi.", origin: "Yunoncha 'lympha' (suv), 'aden' (bez) va 'ektome' (kesish) so'zlaridan.", treatment: "Sentinel limfa tuguni biopsiyasi yoki to'liq limfadenektomiya.", prevention: "Saratonni erta aniqlash.", recommendations: "Jarrohlikdan keyin limfedema rivojlanishini kuzatish.", source: "NCCN saraton davolash qo'llanmasi" },
  { id: "limfogranulematoz", term: "Xodzhkin limfomasi", category: "Onkologiya", shortDesc: "Limfa tizimi saratoni", fullDesc: "Xodzhkin limfomasi — limfa tugunlarida Reed-Sternberg hujayralarining paydo bo'lishi bilan xarakterlanadigan saraton turi. Yoshlarda (15-35) va keksalarda (55+) ko'p uchraydi.", origin: "Ingliz shifokor Thomas Hodgkin nomi bilan (1832).", treatment: "Ximioterapiya (ABVD), nurli davolash, stem hujayra transplantatsiyasi.", prevention: "Sabablar noma'lum — oldini olish qiyin.", recommendations: "Davolash natijasi yaxshi — 80-90% 5 yillik yashash.", source: "NCCN Xodzhkin limfomasi qo'llanmasi" },
  { id: "makrotsitoz", term: "Makrotsitoz", category: "Kasallik", shortDesc: "Eritrotsitlar hajmining kattalashishi", fullDesc: "Makrotsitoz — qizil qon tanachalari (eritrotsitlar) hajmining me'yordan katta bo'lishi. B12 vitamini va folat yetishmovchiligi, jigar kasalligi va alkogolizm sabablar.", origin: "Yunoncha 'makros' (katta) va 'kytos' (hujayra) so'zlaridan.", treatment: "B12 vitamini yoki folat kislota qo'shimchalari, asosiy sababni davolash.", prevention: "Yetarli B12 va folat kislota iste'mol qilish.", recommendations: "Vegetarianlar B12 qo'shimchasi qabul qilishi kerak.", source: "ASH gematologiya qo'llanmasi" },
  { id: "mastit", term: "Mastit", category: "Ginekologiya", shortDesc: "Sut bezi yallig'lanishi", fullDesc: "Mastit — sut bezining, ko'pincha emizish davrida, bakterial infeksiya sababli yallig'lanishi. Og'riq, qizarish, shish va isitma xos belgilar.", origin: "Yunoncha 'mastos' (ko'krak) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Antibiotiklar, emizishni davom ettirish, issiq kompresslar.", prevention: "To'g'ri emizish texnikasi, sut dimlanishiga yo'l qo'ymaslik.", recommendations: "Emizishni to'xtatmaslik — bu davolashga yordam beradi.", source: "ACOG ginekologiya qo'llanmasi" },
  { id: "mediastinit", term: "Mediastinit", category: "Kasallik", shortDesc: "Ko'krak bo'shlig'i o'rta qismining yallig'lanishi", fullDesc: "Mediastinit — ko'krak qafasining o'rta qismi (mediastinum) ning yallig'lanishi. Qizilo'ngach yirtilishi, yurak jarrohligidan keyin va boshqa sabablar. Hayotga xavfli holat.", origin: "Lotincha 'mediastinum' (o'rta qism) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Antibiotiklar, jarrohlik drenaj, intensiv terapiya.", prevention: "Jarrohlik asoratlarini kamaytirish.", recommendations: "Isitma, ko'krak og'rig'i va nafas qiyinligi bo'lsa zudlik bilan shifokorga murojaat.", source: "STS torakal jarrohlik qo'llanmasi" },
  { id: "meningioma", term: "Meningioma", category: "Onkologiya", shortDesc: "Miya pardasi o'smasi", fullDesc: "Meningioma — miya va orqa miya pardalaridan (meninkslar) o'sadigan, ko'pincha xavfsiz (benign) o'sma. Eng ko'p uchraydigan birlamchi miya o'smasi.", origin: "Yunoncha 'meninx' (parda) va '-oma' (o'sma) so'zlaridan.", treatment: "Kuzatish (kichik o'smalar), jarrohlik, stereotaktik nurli davolash.", prevention: "Ionizatsiyalovchi nurlanishdan qochish.", recommendations: "Ko'pchilik meningiomalar sekin o'sadi va jarrohlik talab qilmasligi mumkin.", source: "AANS neyrojarrohlik qo'llanmasi" },
  { id: "mezenterial_tromboz", term: "Mezenterial tromboz", category: "Kardiologiya", shortDesc: "Ichak qon tomirlarining tiqilishi", fullDesc: "Mezenterial tromboz — ichak qon tomir (mezenterial arteriya yoki vena) ning tromb bilan tiqilishi. Ichak nekroziga olib kelishi mumkin. Tezkor jarrohlik kerak.", origin: "Yunoncha 'mesos' (o'rta), 'enteron' (ichak) va 'thrombos' (ivish) so'zlaridan.", treatment: "Shoshilinch jarrohlik, antikoagulyant terapiya, trombektomiya.", prevention: "Atrial fibrillyatsiyani davolash, antikoagulyantlar.", recommendations: "Kuchli qorin og'rig'i va qonli najas bo'lsa zudlik bilan tezkor tibbiy yordam.", source: "ACS jarrohlik qo'llanmasi" },
  { id: "mialgiya", term: "Mialgiya", category: "Kasallik", shortDesc: "Mushak og'rig'i", fullDesc: "Mialgiya — bir yoki bir necha mushaklarning og'rishi. Infeksiya (gripp), zo'riqish, fibromyalgiya, dori ta'sirlari va autoimmun kasalliklar sabablardan.", origin: "Yunoncha 'mys' (mushak) va 'algos' (og'riq) so'zlaridan.", treatment: "NSAIDlar, mushak relaksantlar, fizioterapiya, issiq/sovuq kompresslar.", prevention: "Sport mashqlardan oldin isitish, yetarli uyqu va dam olish.", recommendations: "Uzoq davom etadigan yoki og'ir mialgiyada shifokorga murojaat.", source: "ACR revmatologiya qo'llanmasi" },
  { id: "mielodisplastik", term: "Mielodisplastik sindrom", category: "Onkologiya", shortDesc: "Suyak iligi hujayralari yetilishining buzilishi", fullDesc: "Mielodisplastik sindrom (MDS) — suyak iligidagi hujayralining yetilishi buzilishi va samarasiz qon ishlab chiqarish. Leykemiyaga o'tish xavfi mavjud.", origin: "Yunoncha 'myelos' (ilik), 'dys' (buzilish) va 'plasis' (shakllanish) so'zlaridan.", treatment: "Azasitidin, desiatabin, lenalidomid, suyak iligi transplantatsiyasi.", prevention: "Benzol va kimyoviy moddalarga aloqani kamaytirish.", recommendations: "Gematolog nazoratida muntazam qon tahlillari.", source: "NCCN MDS qo'llanmasi" },
  { id: "miokardit", term: "Miokardit", category: "Kardiologiya", shortDesc: "Yurak mushagining yallig'lanishi", fullDesc: "Miokardit — yurak mushagi (miokard) ning yallig'lanishi. Viruslar (Coxsackie, COVID-19), autoimmun kasalliklar va toksik moddalar sabab. Yurak yetishmovchiligi va aritmiya xavfi.", origin: "Yunoncha 'mys' (mushak), 'kardia' (yurak) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Dam olish, yurak yetishmovchiligi dorilar, immunosuppressorlar (maxsus hollarda).", prevention: "Virus infeksiyalardan himoyalanish, sport o'ynash cheklovlari.", recommendations: "Miokarditdan keyin 3-6 oy jismoniy mashqlardan tiyilish.", source: "ESC miokardit qo'llanmasi" },
  { id: "nefrit_interstitsial", term: "Interstitsial nefrit", category: "Kasallik", shortDesc: "Buyrak interstitsiy to'qimasining yallig'lanishi", fullDesc: "Interstitsial nefrit — buyrakning interstitsial to'qimasining yallig'lanishi. Dorilar (NSAIDlar, antibiotiklar), infeksiyalar va autoimmun sabablar. O'tkir buyrak yetishmovchiligi.", origin: "Lotincha 'interstitium' (oraliq) va 'nephritis' (buyrak yallig'lanishi) so'zlaridan.", treatment: "Sababchi dorini to'xtatish, kortikosteroidlar.", prevention: "Dorilarni ehtiyotkorlik bilan qo'llash.", recommendations: "Buyrak funksiyasini muntazam tekshirish.", source: "KDIGO buyrak kasalliklari qo'llanmasi" },
  { id: "neyropatiya_periferik", term: "Periferik neyropatiya", category: "Nevrologiya", shortDesc: "Periferik nervlar shikastlanishi", fullDesc: "Periferik neyropatiya — periferik nervlarning shikastlanishi. Uvishish, og'riq, kuchsizlanish va sezgi yo'qolishi xos. Diabet, alkogolizm, B12 yetishmovchiligi va dorilar sabab.", origin: "Yunoncha 'neuron' (nerv), 'pathos' (kasallik) va 'periphereia' (chet) so'zlaridan.", treatment: "Asosiy sababni davolash, gabapentin, pregabalin, duloksetin.", prevention: "Qandli diabetni yaxshi nazorat qilish, alkogolni cheklash.", recommendations: "Oyoqlarni har kuni tekshirish (diabetiklar uchun).", source: "AAN nevrologiya qo'llanmasi" },
  { id: "nikturia", term: "Nikturia", category: "Urologiya", shortDesc: "Tungi tez-tez siydik chiqishi", fullDesc: "Nikturia — tunda ikki va undan ko'p marta siydik chiqarish uchun uyg'onish. Prostata giperplaziyasi, diabet, yurak yetishmovchiligi va siydik pufagi kasalliklari sabab.", origin: "Yunoncha 'nyktos' (tun) va 'ouron' (siydik) so'zlaridan.", treatment: "Desmopressin, alfa-blokerlar, anticholinergiklar.", prevention: "Kechqurun suyuqlik iste'molini cheklash, kofein va alkogoldan qochish.", recommendations: "Bazal sababni aniqlash uchun urolog konsultatsiyasi.", source: "ICS urologiya qo'llanmasi" },
  { id: "noma", term: "Noma (kankrum oris)", category: "Kasallik", shortDesc: "Yuz to'qimalarining tez tarqaladigan gangrena", fullDesc: "Noma — og'iz bo'shlig'i va yuz to'qimalarining tez tarqaladigan gangrenasi. Immunitet zaiflanishi, malnnutritsiya va gigiena buzilishi sababli, asosan bolalarda uchraydi.", origin: "Yunoncha 'nome' (yara) so'zidan.", treatment: "Antibiotiklar, to'g'ri ovqatlanish, jarrohlik rekonstruktsiya.", prevention: "Bolalar ovqatlanishini yaxshilash, og'iz gigienasini saqlash, emlash.", recommendations: "Erta davolash tissuelarnimg yo'qolishini kamaytiradi.", source: "JSST noma qo'llanmasi" },
  { id: "osteomielit", term: "Osteomielit", category: "Kasallik", shortDesc: "Suyak infeksiyasi", fullDesc: "Osteomielit — suyakning bakterial (kamdan-kam fungal) infeksiyasi va yallig'lanishi. Gematogen yo'l, shikast yoki jarrohlikdan keyin rivojlanishi mumkin.", origin: "Yunoncha 'osteon' (suyak), 'myelos' (ilik) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Uzoq muddatli antibiotik terapiya (4-6 hafta), jarrohlik debridment.", prevention: "Ochiq shikastlarni toza saqlash, qandli diabetni nazorat qilish.", recommendations: "MRT eng sezgir diagnostika usuli.", source: "IDSA suyak infeksiyalari qo'llanmasi" },
  { id: "otalgia", term: "Otalgia", category: "Otorinolaringologiya", shortDesc: "Quloq og'rig'i", fullDesc: "Otalgia — quloq og'rig'i. Birlamchi (quloq kasalligi) yoki ikkilamchi (irradia — jag', tomoq, tish va boshqa sabablar) bo'lishi mumkin. Bolalarda ko'p uchraydi.", origin: "Yunoncha 'ous' (quloq) va 'algos' (og'riq) so'zlaridan.", treatment: "Antibiotik tomchilar, og'riqsizlantirgichlar, issiq kompresslar.", prevention: "Quloqni toza saqlash, suzishda quloq tiqini ishlatish.", recommendations: "2-3 kun davom etadigan quloq og'rig'ida shifokorga murojaat.", source: "AAO-HNS otorinolaringologiya qo'llanmasi" },
  { id: "otorinolaringologiya_ts", term: "Otoskleroz", category: "Otorinolaringologiya", shortDesc: "O'rta quloq suyagining qotishi", fullDesc: "Otoskleroz — o'rta quloqdagi uzangi (stapes) suyagining g'ayritabiiy o'sishi va qotishi. Eshitish qobiliyatining asta-sekin pasayishi xos. Oilaviy moyillik bor.", origin: "Yunoncha 'ous' (quloq) va 'skleros' (qattiq) so'zlaridan.", treatment: "Stapedektomiya jarrohlik, eshitish apparati.", prevention: "Genetik moyillik — oldini olish qiyin.", recommendations: "Eshitish pasayganda audiologik tekshiruvdan o'tish.", source: "AAO-HNS otologiya qo'llanmasi" },
  { id: "pankreatit_surunkali", term: "Surunkali pankreatit", category: "Gastroenterologiya", shortDesc: "Oshqozon osti bezining surunkali yallig'lanishi", fullDesc: "Surunkali pankreatit — oshqozon osti bezining qaytmas yallig'lanishi va fibrozy. Alkogol, tosh va genetik sabablar. Og'riq, steatorea va qandli diabet rivojlanadi.", origin: "Yunoncha 'pankreas' (hammasi go'sht) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Og'riqni boshqarish, pankreas fermentlari, insulin, jarrohlik.", prevention: "Alkogolni to'xtatish, chekishni tashllash.", recommendations: "Yog'li ovqatni cheklash, kichik porsiyalarda tez-tez ovqatlanish.", source: "ACG pankreatit qo'llanmasi" },
  { id: "paraproktit", term: "Paraproktit", category: "Kasallik", shortDesc: "To'g'ri ichak atrofi to'qima yallig'lanishi", fullDesc: "Paraproktit — to'g'ri ichak atrofidagi to'qimaning yiringli yallig'lanishi va absess hosil bo'lishi. Og'riq, shish va isitma xos belgilar. Anal fistula shakllanishi mumkin.", origin: "Yunoncha 'para' (yonida), 'proktos' (to'g'ri ichak) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Jarrohlik drenaj, antibiotiklar.", prevention: "Shaxsiy gigiena, ich qotishdan qochish.", recommendations: "O'z vaqtida davolanmasa surunkali fistula shakllanadi.", source: "ASCRS kolorektal jarrohlik qo'llanmasi" },
  { id: "paronixiya", term: "Paronixiya", category: "Dermatologiya", shortDesc: "Tirnoq atrofi to'qimaning yallig'lanishi", fullDesc: "Paronixiya — tirnoq atrofidagi teri va yumshoq to'qimaning yallig'lanishi. O'tkir (bakterial) va surunkali (fungal) turlari mavjud. Qo'l tirnoqlarida ko'p uchraydi.", origin: "Yunoncha 'para' (yonida) va 'onyx' (tirnoq) so'zlaridan.", treatment: "Issiq suvli vannalar, antibiotiklar, antifungallar, jarrohlik drenaj.", prevention: "Tirnoqlarni to'g'ri kesish, qo'llarni quruq saqlash.", recommendations: "Tirnoq o'chirish yoki tirnoq atrofi po'stini qirqishdan qochish.", source: "AAD dermatologiya qo'llanmasi" },
  { id: "perikardit_konstruktiv", term: "Konstruktiv perikardit", category: "Kardiologiya", shortDesc: "Yurak xaltasining qalinlashishi va qotishi", fullDesc: "Konstruktiv perikardit — yurak xaltasi (perikard) ning surunkali yallig'lanish sababli qalinlashishi va qotishi. Yurakni siqib, qon to'lishini cheklaydi.", origin: "Yunoncha 'peri' (atrofida), 'kardia' (yurak) va lotincha 'constrictio' (siqish) so'zlaridan.", treatment: "Perikardiektomiya (jarrohlik), diuretiklar.", prevention: "Perikardatni o'z vaqtida davolash.", recommendations: "KT yoki MRT bilan perikard qalinligini baholash.", source: "ESC perikard kasalliklari qo'llanmasi" },
  { id: "peritonit", term: "Peritonit", category: "Kasallik", shortDesc: "Qorin parda yallig'lanishi", fullDesc: "Peritonit — qorin pardasining (peritoneum) yallig'lanishi. Appenditsit yorilib ketishi, yara perforatsiyasi va boshqa sabablar. Hayotga xavfli — tezkor jarrohlik kerak.", origin: "Yunoncha 'peritonaion' (tortilgan) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Shoshilinch jarrohlik, antibiotiklar, intensiv terapiya.", prevention: "Appenditsit va yara kasalligini o'z vaqtida davolash.", recommendations: "Kuchli qorin og'rig'i, isitma va qotib turish belgilari bo'lsa darhol tez yordam chaqiring.", source: "SIS abdominal infeksiyalar qo'llanmasi" },
  { id: "plazmaferez", term: "Plazmaferez", category: "Diagnostika", shortDesc: "Qon plazmasini almashtirish protsedurasi", fullDesc: "Plazmaferez — bemorning qon plazmasini ajratib olib, yangi plazma yoki albumin eritmasi bilan almashtirish. Autoimmun kasalliklar va toksinlarni yo'q qilishda qo'llaniladi.", origin: "Yunoncha 'plasma' (shakllangan) va 'aphaeresis' (ajratish) so'zlaridan.", treatment: "Guillain-Barré sindromi, miasteniya gravis, trombotsitik purpura va boshqalar.", prevention: "Diagnostik va terapevtik vosita.", recommendations: "Venoz kirish uchun maxsus kateter o'rnatilishi kerak.", source: "ASFA plazmaferez qo'llanmasi" },
  { id: "plevrit", term: "Plevrit", category: "Kasallik", shortDesc: "O'pka pardasining yallig'lanishi", fullDesc: "Plevrit — o'pka pardasi (plevra) ning yallig'lanishi. Nafas olish paytida keskin og'riq xos belgi. Pnevmoniya, tuberkulyoz va saraton sabab bo'lishi mumkin.", origin: "Yunoncha 'pleura' (qovurg'a, yon) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Asosiy sababni davolash, NSAIDlar, torakosentez (suyuqlik to'planganda).", prevention: "Pnevmoniyani o'z vaqtida davolash.", recommendations: "Nafas olishda og'riq bo'lsa shifokorga murojaat.", source: "BTS plevra kasalliklari qo'llanmasi" },
  { id: "poliartrit", term: "Poliartrit", category: "Kasallik", shortDesc: "Bir nechta bo'g'imning yallig'lanishi", fullDesc: "Poliartrit — beshta va undan ko'p bo'g'imning bir vaqtda yallig'lanishi. Revmatoid artrit, tizimli qizil bo'richa va boshqa autoimmun kasalliklar sabab.", origin: "Yunoncha 'poly' (ko'p) va 'arthritis' (bo'g'im yallig'lanishi) so'zlaridan.", treatment: "NSAIDlar, metotreksat, biologik dorilar, kortikosteroidlar.", prevention: "Erta tashxis va davolash bo'g'im buzilishini kamaytiradi.", recommendations: "Revmatolog nazoratida muntazam tekshiruvlar.", source: "ACR revmatologiya qo'llanmasi" },
  { id: "polineyropatiya", term: "Polineyropatiya", category: "Nevrologiya", shortDesc: "Ko'p nervlarning bir vaqtda shikastlanishi", fullDesc: "Polineyropatiya — bir nechta periferik nervlarning bir vaqtda shikastlanishi. Uvishish qo'l va oyoq barmoqlaridan boshlanib, yuqoriga tarqaladi. Diabet eng ko'p sabab.", origin: "Yunoncha 'poly' (ko'p), 'neuron' (nerv) va 'pathos' (kasallik) so'zlaridan.", treatment: "Asosiy sababni davolash, gabapentin, pregabalin, fizioterapiya.", prevention: "Qandli diabetni nazorat qilish, alkogolni cheklash.", recommendations: "Oyoq parvarishi va travmadan himoyalanish.", source: "AAN nevrologiya qo'llanmasi" },
  { id: "prostatit", term: "Prostatit", category: "Urologiya", shortDesc: "Prostata bezining yallig'lanishi", fullDesc: "Prostatit — prostata bezining yallig'lanishi. O'tkir bakterial, surunkali bakterial, surunkali pelvik og'riq sindromi va asimptomatik turlari mavjud.", origin: "Yunoncha 'prostates' (oldinda turuvchi) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Antibiotiklar, alfa-blokerlar, NSAIDlar, fizioterapiya.", prevention: "Yetarli suyuqlik iste'mol qilish, jinsiy faollikni saqlash.", recommendations: "Surunkali belgilarda urolog konsultatsiyasi.", source: "EAU urologiya qo'llanmasi" },
  { id: "psixosomatik", term: "Psixosomatik buzilishlar", category: "Psixiatriya", shortDesc: "Ruhiy sabablarga bog'liq jismoniy belgilar", fullDesc: "Psixosomatik buzilishlar — ruhiy, emotsional va stress omillari sababli paydo bo'ladigan jismoniy shikoyatlar. Bosh og'rig'i, oshqozon og'rig'i va yurak urishi tezlashishi kabi belgilar.", origin: "Yunoncha 'psykhe' (ruh) va 'soma' (tana) so'zlaridan.", treatment: "Psixoterapiya (KBT), antidepressantlar, stress boshqarish.", prevention: "Stress boshqarish ko'nikmalari, dam olish mashqlari.", recommendations: "Jismoniy sabablar istisno qilingach, psixolog/psixiatriga murojaat.", source: "APA psixiatriya qo'llanmasi" },
  { id: "rabdomioliz", term: "Rabdomioliz", category: "Kasallik", shortDesc: "Skelet mushaklari parchalanishi", fullDesc: "Rabdomioliz — skelet mushaklari hujayralari parchalanib, miyoglobin va boshqa moddalar qonga tushishi. O'tkir buyrak yetishmovchiligi va hatto o'lim xavfi bor.", origin: "Yunoncha 'rhabdos' (tayoqcha), 'mys' (mushak) va 'lysis' (parchalanish) so'zlaridan.", treatment: "Kuchli infuzion terapiya, elektrolit nazorati, dializ (kerak bo'lganda).", prevention: "Haddan tashqari jismoniy zo'riqishdan qochish, yetarli suyuqlik ichish.", recommendations: "Og'ir jismoniy mashqdan keyin mushak og'rig'i va to'q rangli siydik bo'lsa shifokorga murojaat.", source: "NEJM rabdomioliz qo'llanmasi" },
  { id: "reflyuks_nefropatiya", term: "Reflyuks nefropatiya", category: "Urologiya", shortDesc: "Siydik qayta oqishi sababli buyrak shikastlanishi", fullDesc: "Reflyuks nefropatiya — vezikoureeral reflyuks (siydik pufagidan buyrakka qayta oqish) sababli buyrak to'qimasining shikastlanishi. Bolalarda ko'p uchraydi.", origin: "Lotincha 'refluxus' (qayta oqish) va yunoncha 'nephros' (buyrak) so'zlaridan.", treatment: "Antibiotik profilaktika, jarrohlik (reimplantatsiya), endoskopik davolash.", prevention: "Siydik yo'li infeksiyalarini o'z vaqtida davolash.", recommendations: "Bolalarda takroriy siydik yo'li infeksiyasida albatta tekshirish.", source: "EAU pediatrik urologiya qo'llanmasi" },
  { id: "retrobulbar_nevrit", term: "Retrobulbar nevrit", category: "Oftalmologiya", shortDesc: "Ko'z nervi yallig'lanishi", fullDesc: "Retrobulbar nevrit — ko'z nervi (optik nerv) ning ko'z soqqasi orqasidagi qismining yallig'lanishi. Ko'rish keskin pasayishi, ko'z og'rig'i va rang ko'rish buzilishi xos. Tarqoq skleroz bilan bog'liq bo'lishi mumkin.", origin: "Lotincha 'retro' (orqada), 'bulbus' (soqqa) va 'neuritis' (nerv yallig'lanishi) so'zlaridan.", treatment: "Yuqori dozali kortikosteroidlar (metilprednizolon IV).", prevention: "Tarqoq sklerozni erta aniqlash va davolash.", recommendations: "Ko'rish keskin pasaysa zudlik bilan oftalmologga murojaat.", source: "AAO neyro-oftalmologiya qo'llanmasi" },
  { id: "sarkoidoz", term: "Sarkoidoz", category: "Immunologiya", shortDesc: "Organlarda granulomalar hosil bo'lishi", fullDesc: "Sarkoidoz — turli organlarda (o'pka, teri, ko'z, jigar) nokazeoz granulomalar hosil bo'ladigan tizimli kasallik. Sababi noma'lum. 20-40 yoshlarda ko'p uchraydi.", origin: "Yunoncha 'sarx' (go'sht) va 'eidos' (ko'rinish) so'zlaridan.", treatment: "Kortikosteroidlar, metotreksat, azatioprin.", prevention: "Sabablar noma'lum — oldini olish qiyin.", recommendations: "Ko'p hollarda o'z-o'zidan tuzaladi, lekin nazorat kerak.", source: "ATS/ERS sarkoidoz qo'llanmasi" },
  { id: "sialadenid", term: "Sialadenid", category: "Stomatologiya", shortDesc: "So'lak bezi yallig'lanishi", fullDesc: "Sialadenid — so'lak bezlarining yallig'lanishi. Bakterial infeksiya, tosh va viruslar (epidemik parotit) sabab. Og'riq, shish va quruq og'iz belgilari.", origin: "Yunoncha 'sialon' (so'lak), 'aden' (bez) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Antibiotiklar, so'lak bezini massaj qilish, tosh olib tashlash.", prevention: "Og'iz gigienasini saqlash, yetarli suyuqlik iste'mol qilish.", recommendations: "Nordon mevalar yeyish so'lak ajralishini rag'batlantiradi.", source: "AAO-HNS bosh-bo'yin jarrohlik qo'llanmasi" },
  { id: "sinusit_surunkali", term: "Surunkali sinusit", category: "Otorinolaringologiya", shortDesc: "Burun bo'shliqlari surunkali yallig'lanishi", fullDesc: "Surunkali sinusit — burun bo'shliqlarining 12 haftadan ortiq davom etadigan yallig'lanishi. Burun bitishligi, ajralma, yuz og'rig'i va hid bilish buzilishi xos.", origin: "Lotincha 'sinus' (bo'shliq) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Nazal kortikosteroidlar, antibiotiklar, burun yuvish, jarrohlik (FESS).", prevention: "Allergiyani davolash, shamollatish, chekishni tashllash.", recommendations: "Burunni tuz eritmasi bilan muntazam yuvish.", source: "EPOS sinusit qo'llanmasi" },
  { id: "skolioz", term: "Skolioz", category: "Travmatologiya", shortDesc: "Umurtqa pog'onasi egriligi", fullDesc: "Skolioz — umurtqa pog'onasining yon tomonga 10 gradusdan ko'p egilishi. Idiopatik (sababsiz) turi 80% hollarda uchraydi. O'smirlik davrida ko'p aniqlanadi.", origin: "Yunoncha 'skolios' (egri) so'zidan.", treatment: "Kuzatish, korset (Cobb burchagi 25-40°), jarrohlik (40° dan yuqori).", prevention: "Erta aniqlash — maktab skriningida tekshirish.", recommendations: "Ortoped nazoratida muntazam tekshiruvlar, suzish foydali sport.", source: "SRS skolioz qo'llanmasi" },
  { id: "spermatotsele", term: "Spermatotsele", category: "Urologiya", shortDesc: "Moyak orqasidagi kista", fullDesc: "Spermatotsele — epididimis (moyak ustki qo'shimchasi) da sperma to'plangan kista. Ko'pincha og'riqsiz va tasodifan aniqlanadi. Xavfsiz holat.", origin: "Yunoncha 'sperma' (urug') va 'kele' (shish) so'zlaridan.", treatment: "Kuzatish, og'riq bo'lsa jarrohlik olib tashlash.", prevention: "Maxsus oldini olish kerak emas.", recommendations: "O'z-o'zidan so'rilmasligi mumkin, lekin xavfsiz holat.", source: "EAU urologiya qo'llanmasi" },
  { id: "spondilolistez", term: "Spondilolistez", category: "Travmatologiya", shortDesc: "Umurtqaning oldingi sirpanishi", fullDesc: "Spondilolistez — bitta umurtqaning pastdagi umurtqaga nisbatan oldingi tomonga sirpanishi. Bel og'rig'i, oyoqqa tarqaladigan og'riq va yurish qiyinligi xos.", origin: "Yunoncha 'spondylos' (umurtqa) va 'olisthesis' (sirpanish) so'zlaridan.", treatment: "Fizioterapiya, NSAIDlar, korset, jarrohlik (fusion).", prevention: "Sport mashqlarda to'g'ri texnika, bel mushaklarini mustahkamlash.", recommendations: "I-II daraja — konservativ, III-IV daraja — jarrohlik ko'rib chiqiladi.", source: "NASS umurtqa qo'llanmasi" },
  { id: "steatoz", term: "Steatoz (yog'li jigar)", category: "Gastroenterologiya", shortDesc: "Jigarda yog' to'planishi", fullDesc: "Steatoz — jigar hujayralarida yog'ning ortiqcha to'planishi. Alkogollik va alkogolsiz (NAFLD/MASLD) turlari. Steatogepatit va tsirrozga o'tishi mumkin.", origin: "Yunoncha 'stear' (yog') va '-osis' (holat) so'zlaridan.", treatment: "Tana vaznini kamaytirish, jismoniy faollik, alkogolni to'xtatish.", prevention: "Sog'lom ovqatlanish, sport, me'yordagi tana vazni.", recommendations: "Jigar UZI va fermentlarini muntazam tekshirish.", source: "AASLD NAFLD qo'llanmasi" },
  { id: "stenokardiya", term: "Stenokardiya (angina pectoris)", category: "Kardiologiya", shortDesc: "Ko'krak qisishi — yurak og'rig'i", fullDesc: "Stenokardiya — yurak mushagiga yetarli qon bormay qolishi sababli ko'krakda og'riq yoki diskomfort. Barqaror va nobarqaror turlari mavjud. Koronar arteriya kasalligining belgisi.", origin: "Yunoncha 'stenos' (tor) va 'kardia' (yurak) so'zlaridan.", treatment: "Nitroglitserin, beta-blokerlar, kalsiy kanal blokerlar, stentlash.", prevention: "Sog'lom turmush tarzi, xolesterinni nazorat qilish, chekishni tashllash.", recommendations: "Ko'krak og'rig'i 15 daqiqadan ko'p davom etsa tez yordam chaqiring.", source: "ACC/AHA barqaror stenokardiya qo'llanmasi" },
  { id: "streptodermiya", term: "Streptodermiya", category: "Dermatologiya", shortDesc: "Streptokokk sababli teri infeksiyasi", fullDesc: "Streptodermiya — A guruhi beta-gemolitik streptokokk sababli teri infeksiyasi. Bolalarda ko'p uchraydi. Pufakchalar, qo'ng'ir qobiqlar va qichish xos.", origin: "Streptokokk bakteriyasi va yunoncha 'derma' (teri) so'zlaridan.", treatment: "Antibiotiklar (amoksitsillin, sefalosporinlar), topikal antiseptiklar.", prevention: "Shaxsiy gigiena, jarohatlarni toza saqlash.", recommendations: "Yuqumli — bola tuzalmaguncha jamoatchilik joylariga bormaslik.", source: "AAD teri infeksiyalari qo'llanmasi" },
  { id: "subluksatsiya", term: "Subluksatsiya", category: "Travmatologiya", shortDesc: "Bo'g'imning qisman chiqishi", fullDesc: "Subluksatsiya — bo'g'im yuzalarining to'liq emas, qisman ajralishi. Luksatsiya (to'liq chiqish) dan farqli ravishda bo'g'im yuzalari qisman kontaktda qoladi.", origin: "Lotincha 'sub' (ostida) va 'luxatio' (chiqish) so'zlaridan.", treatment: "Repositsiya (joyiga qo'yish), immobilizatsiya, fizioterapiya.", prevention: "Sport jarohatlardan himoyalanish, bo'g'imlarni mustahkamlash.", recommendations: "O'z-o'zini davolashdan qoching, travmatologga murojaat qiling.", source: "AAOS travmatologiya qo'llanmasi" },
  { id: "talassemiya", term: "Talassemiya", category: "Kasallik", shortDesc: "Irsiy qon kasalligi", fullDesc: "Talassemiya — gemoglobin ishlab chiqarishning buzilishi bilan kechadigan irsiy qon kasalliklari guruhi. Alfa va beta turlari mavjud. Anemiya, suyak deformatsiyasi va splenomegaliya xos.", origin: "Yunoncha 'thalassa' (dengiz) va 'haima' (qon) so'zlaridan — O'rta dengiz bo'ylarida ko'p uchragani uchun.", treatment: "Qon quyish, temir chelator terapiya (deferasiroks), suyak iligi transplantatsiyasi.", prevention: "Genetik maslahat, prenatal diagnostika.", recommendations: "Temir ortiqchaligini nazorat qilish muhim.", source: "TIF talassemiya qo'llanmasi" },
  { id: "tendinit", term: "Tendinit", category: "Travmatologiya", shortDesc: "Pay yallig'lanishi", fullDesc: "Tendinit — paylarning yallig'lanishi. Ortiqcha zo'riqish, takroriy harakatlar va yosh bilan bog'liq o'zgarishlar sabab. Yelka, tirsak, bilak va Axill payida ko'p uchraydi.", origin: "Lotincha 'tendo' (pay) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Dam olish, muz, NSAIDlar, fizioterapiya, kortikosteroid in'ektsiyasi.", prevention: "Sport mashqlaridan oldin isitish, ortiqcha yukdan qochish.", recommendations: "Og'riq 2 haftadan ko'p davom etsa shifokorga murojaat.", source: "AAOS ortopediya qo'llanmasi" },
  { id: "tireoidit_hashimoto", term: "Hashimoto tireoiditi", category: "Endokrinologiya", shortDesc: "Autoimmun qalqonsimon bez yallig'lanishi", fullDesc: "Hashimoto tireoiditi — qalqonsimon bezning autoimmun yallig'lanishi. Gipotireoidizmning eng ko'p uchraydigan sababi. Anti-TPO va anti-Tg antijemlari qonda aniqlanadi.", origin: "Yapon shifokor Hakaru Hashimoto nomi bilan (1912).", treatment: "Levotiroksin almashtirish terapiyasi.", prevention: "Autoimmun kasallik — oldini olish qiyin.", recommendations: "TSH darajasini har 6-12 oyda tekshirish.", source: "ATA qalqonsimon bez qo'llanmasi" },
  { id: "trakeostomiya", term: "Trakeostomiya", category: "Jarrohlik", shortDesc: "Traxeyaga teshik ochish jarrohlik", fullDesc: "Trakeostomiya — nafas yo'lini ta'minlash uchun traxeya devoriga jarrohlik yo'li bilan teshik ochish va trakeostomik trubka o'rnatish. Uzoq muddatli sun'iy nafas olish kerak bo'lganda.", origin: "Yunoncha 'trakheia' (nafas nay) va 'stoma' (og'iz, teshik) so'zlaridan.", treatment: "Perkutan yoki ochiq jarrohlik texnikasi.", prevention: "Nafas yo'li tiqilishi sabablarini bartaraf etish.", recommendations: "Trakeostomik trubkani muntazam tozalash va almashtirish.", source: "AAOHNS bosh-bo'yin jarrohlik qo'llanmasi" },
  { id: "trombotsitopenik_purpura", term: "Idiopatik trombotsitopenik purpura", category: "Kasallik", shortDesc: "Autoimmun trombotsit kamayishi", fullDesc: "ITP — immunitet tizimi trombotsitlarni yo'q qilib, qon ketish xavfini oshiradigan autoimmun kasallik. Teridagi ko'karishlar va teri osti qon ketishlari xos.", origin: "Yunoncha 'thrombos' (ivish), 'kytos' (hujayra), 'penia' (kamlik) va 'purpura' (binafsha) so'zlaridan.", treatment: "Kortikosteroidlar, immunoglobulin, rituksimab, splenektomiya.", prevention: "Autoimmun kasallik — oldini olish qiyin.", recommendations: "Og'ir jismoniy mashqlar va travmadan ehtiyot bo'lish.", source: "ASH ITP qo'llanmasi" },
  { id: "uvelit", term: "Uveit", category: "Oftalmologiya", shortDesc: "Ko'z qon pardasi yallig'lanishi", fullDesc: "Uveit — ko'zning uvea qatlamining (iris, silijar tanasi, xorioid) yallig'lanishi. Ko'z og'rig'i, qizarish, ko'rish xiralashishi va yorug'likka sezgirlik xos belgilar.", origin: "Lotincha 'uvea' (uzum) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Topikal kortikosteroidlar, sikloplegiklar, tizimli immunosuppressorlar.", prevention: "Asosiy autoimmun yoki infeksion sababni davolash.", recommendations: "Ko'rish o'zgarishi bo'lsa zudlik bilan oftalmologga murojaat.", source: "AAO uveit qo'llanmasi" },
  { id: "faringit_surunkali", term: "Surunkali faringit", category: "Otorinolaringologiya", shortDesc: "Tomoq shilliq qavatining surunkali yallig'lanishi", fullDesc: "Surunkali faringit — tomoq shilliq qavatining uzoq muddatli yallig'lanishi. Quruqlik, g'adirlik hissi, yo'tal va tomoq og'rig'i xos. Chekish, chang va reflyuks sabab.", origin: "Yunoncha 'pharynx' (tomoq) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Sababni bartaraf etish, antiseptik chayish eritmalari, tomoqni namlash.", prevention: "Chekishni tashllash, changdan himoyalanish, GERD ni davolash.", recommendations: "Iliq suyuqliklar ichish, quruq havoda namlagich ishlatish.", source: "AAO-HNS otorinolaringologiya qo'llanmasi" },
  { id: "fenilketonuriya", term: "Fenilketonuriya (PKU)", category: "Genetika", shortDesc: "Fenilalanin metabolizmi buzilishi", fullDesc: "Fenilketonuriya — fenilalanin aminokislotasini metabolizm qila olmaydigan irsiy kasallik. Davolanmasa aqliy rivojlanish orqada qoladi. Yangi tug'ilganlar skriningida aniqlanadi.", origin: "Fenilalanin aminokislotasi va yunoncha 'ouron' (siydik) so'zlaridan.", treatment: "Fenilalaninsiz maxsus dieta, sapropterin (BH4), gen terapiya (ishlab chiqilmoqda).", prevention: "Yangi tug'ilganlar skriningi muhim.", recommendations: "Umr bo'yi maxsus dieta saqlash kerak.", source: "ACMG genetika qo'llanmasi" },
  { id: "fibromyalgiya", term: "Fibromyalgiya", category: "Kasallik", shortDesc: "Keng tarqalgan mushak og'rig'i sindromi", fullDesc: "Fibromyalgiya — butun tanada keng tarqalgan mushak og'rig'i, charchoq, uyqu buzilishi va kognitiv qiyinchiliklar bilan kechadigan surunkali holat.", origin: "Lotincha 'fibra' (tola), yunoncha 'mys' (mushak) va 'algos' (og'riq) so'zlaridan.", treatment: "Duloksetin, pregabalin, amitriptilin, jismoniy mashqlar, KBT.", prevention: "Stress boshqarish, muntazam jismoniy faollik.", recommendations: "Aerobik mashqlar og'riqni kamaytiradi.", source: "ACR fibromyalgiya qo'llanmasi" },
  { id: "fistula_anal", term: "Anal fistula", category: "Kasallik", shortDesc: "To'g'ri ichak va teri orasida g'ayritabiiy yo'l", fullDesc: "Anal fistula — to'g'ri ichak (yoki anal kanal) va teri yuzasi o'rtasida g'ayritabiiy yo'l (kanal). Ko'pincha paraproktit asoratidir. Yiringli ajralma va og'riq xos.", origin: "Lotincha 'fistula' (quvur, yo'l) so'zidan.", treatment: "Jarrohlik (fistulotomiya, fistulektomiya, LIFT, seton).", prevention: "Paraproktitni o'z vaqtida davolash.", recommendations: "O'z-o'zidan tuzalmaydigan kasallik — jarrohlik kerak.", source: "ASCRS kolorektal jarrohlik qo'llanmasi" },
  { id: "xolesteatoma", term: "Xolesteatoma", category: "Otorinolaringologiya", shortDesc: "O'rta quloqda teri to'qimasi to'planishi", fullDesc: "Xolesteatoma — o'rta quloqda keratinizatsiyalangan teri hujayralarining g'ayritabiiy to'planishi. Suyaklarni yemirishi va eshitish yo'qolishiga olib kelishi mumkin.", origin: "Yunoncha 'khole' (o't), 'stear' (yog') va '-oma' (o'sma) so'zlaridan.", treatment: "Jarrohlik olib tashlash (mastoidektomiya bilan yoki holda).", prevention: "O'rta quloq yallig'lanishini o'z vaqtida davolash.", recommendations: "Jarrohlikdan keyin uzoq muddatli kuzatish kerak.", source: "AAO-HNS otologiya qo'llanmasi" },
  { id: "tseliakiya", term: "Tseliakiya", category: "Gastroenterologiya", shortDesc: "Glutenga nisbatan autoimmun reaktsiya", fullDesc: "Tseliakiya — glutenga (bug'doy, arpa, javdar oqsillariga) nisbatan autoimmun reaktsiya. Ingichka ichak shilliq qavatini zararlaydi, so'rilish buziladi.", origin: "Yunoncha 'koilia' (qorin bo'shlig'i) so'zidan.", treatment: "Umr bo'yi glutensiz dieta.", prevention: "Genetik moyillik — oldini olish qiyin.", recommendations: "Glutensiz mahsulotlar haqida dietolog bilan maslahat.", source: "ACG tseliakiya qo'llanmasi" },
  { id: "tservitsit", term: "Tservitsit", category: "Ginekologiya", shortDesc: "Bachadon bo'yni yallig'lanishi", fullDesc: "Tservitsit — bachadon bo'ynining (serviks) yallig'lanishi. Xlamidiya, gonoreya va boshqa infeksiyalar sabab. Ajralma, kontakt qon ketish va qorin osti og'rig'i xos.", origin: "Lotincha 'cervix' (bo'yin) va '-itis' (yallig'lanish) so'zlaridan.", treatment: "Antibiotiklar (azitromitsin, doksitsiklin), asosiy infeksiyani davolash.", prevention: "Himoyalangan jinsiy aloqa, muntazam ginekologik tekshiruv.", recommendations: "Jinsiy sherik ham davolanishi kerak.", source: "CDC JYIK davolash qo'llanmasi" },
  { id: "enukolyatsiya", term: "Enuklatsiya (ko'z)", category: "Oftalmologiya", shortDesc: "Ko'z soqqasini jarrohlik bilan olib tashlash", fullDesc: "Enuklatsiya — ko'z soqqasining to'liq olib tashlanishi. Retinoblastoma, og'ir travma va ko'r og'riqli ko'zda qo'llaniladi. Sun'iy ko'z (protez) o'rnatiladi.", origin: "Lotincha 'enucleare' (yadro olib tashlash) so'zidan.", treatment: "Jarrohlik — orbital implant va sun'iy ko'z protezi.", prevention: "Ko'z saratonlarini erta aniqlash.", recommendations: "Psixologik qo'llab-quvvatlash va protez parvarishi.", source: "AAO okuplastika qo'llanmasi" },
];

export default termsExtra500_4;
